import type { TagStatus } from '@/lib/types';

/**
 * Hours out of the water, from the tag's own count of its transmissions.
 *
 * Every Wildlife Computers Status message carries `Transmits`: "the number of
 * Argos transmissions generated by the tag. NOT the number of messages
 * received by Argos" (WC Spreadsheet File Descriptions). A popped-up tag
 * transmits only while its wet/dry sensor reads dry, once per repetition
 * period, so the counter's rise between two Status messages is the time it
 * spent dry, whether or not any satellite was listening.
 *
 * That separates the two reasons a tag goes quiet:
 *   - the counter barely moves: the tag is wet (awash, sunk, in surf), so it
 *     is not transmitting at all;
 *   - the counter climbs at full rate but few messages arrive: the tag is dry
 *     and transmitting, and something round it is blocking the signal.
 * MiniPAT 33938 spent a week in a boat lockup counting a steady 57–64 an
 * hour, a full minute-by-minute schedule, while satellites heard a fraction
 * of what they heard when it floated: covered, not wet.
 *
 * The counter is reported in steps (64 or 128 transmissions on MiniPATs,
 * about an hour or two at one a minute), so only spans of several hours give
 * a usable figure; shorter ones are merged.
 *
 * The count at the first Status message is no guide to when the tag first
 * came out of the water: it includes transmissions made on the bench before
 * deployment (33938 showed 320 forty minutes after release, 285931 showed
 * 192). Only differences between messages are used.
 */

export interface CounterWindow {
  from: Date;
  to: Date;
  hours: number;
  /** Transmissions the tag made in the window. */
  sent: number;
  /** Hours dry, from sent × period; null without a period. */
  dryHours: number | null;
  /** dryHours / hours, capped at 1; null without a period. */
  dryFraction: number | null;
  /** Messages satellites received in the window; null without message times. */
  heard: number | null;
  /** heard / sent: how much of what it sent got through. */
  heardPerSent: number | null;
  /** Window starts at or after the stop (resting), when a stop is known. */
  resting: boolean;
}

export type DryVerdict = 'dry' | 'mostly_dry' | 'partly_wet' | 'wet';

export interface TransmitCounter {
  /** Counter resolution, transmissions. */
  step: number;
  /** Seconds between transmissions while dry; null when unknown. */
  periodS: number | null;
  windows: CounterWindow[];
  /** Figures over the whole resting period (or the whole record without one). */
  latest: {
    from: Date;
    to: Date;
    hours: number;
    sent: number;
    dryFraction: number | null;
    verdict: DryVerdict | null;
    heardPerSent: number | null;
  } | null;
  /** heard/sent while afloat, for comparison; null without a stop or message times. */
  afloatHeardPerSent: number | null;
  reasoning: string;
}

/** Spans shorter than this are merged into the next: the counter's step is an hour or two. */
const MIN_SPAN_H = 6;

const fmt = (d: Date) =>
  d.toLocaleString('en-GB', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit', timeZone: 'UTC' }) + 'Z';

function verdictOf(f: number): DryVerdict {
  return f >= 0.85 ? 'dry' : f >= 0.5 ? 'mostly_dry' : f >= 0.15 ? 'partly_wet' : 'wet';
}

const VERDICT_TEXT: Record<DryVerdict, string> = {
  dry: 'out of the water the whole time',
  mostly_dry: 'out of the water most of the time',
  partly_wet: 'wet much of the time: awash, in the surf line or under spray',
  wet: 'wet nearly the whole time: underwater, awash or buried in wet sand',
};

export function analyzeTransmitCounter(
  statuses: TagStatus[],
  messageTimes: { date: Date }[],
  periodS: number | null,
  restingSince: Date | null = null,
  releaseDate: Date | null = null
): TransmitCounter | null {
  // One reading per moment, after release, in time order. Counters only rise;
  // a fall is a reset or a garbled message and is dropped.
  const pts: { date: Date; n: number }[] = [];
  for (const s of [...statuses].sort((a, b) => a.date.getTime() - b.date.getTime())) {
    if (s.transmits === null || s.transmits === undefined || !Number.isFinite(s.transmits)) continue;
    if (releaseDate && s.date < releaseDate) continue;
    const prev = pts[pts.length - 1];
    if (prev && s.transmits < prev.n) continue;
    if (prev && s.date.getTime() === prev.date.getTime()) continue;
    pts.push({ date: s.date, n: s.transmits });
  }
  if (pts.length < 2) return null;

  const diffs = pts.slice(1).map((p, i) => p.n - pts[i].n).filter((d) => d > 0);
  const step = diffs.length ? Math.min(...diffs) : 0;

  const times = messageTimes.map((m) => m.date.getTime()).sort((a, b) => a - b);
  const heardBetween = (a: number, b: number) => {
    if (!times.length) return null;
    let n = 0;
    for (const t of times) if (t > a && t <= b) n++;
    return n;
  };

  const windows: CounterWindow[] = [];
  let anchor = pts[0];
  for (const p of pts.slice(1)) {
    const hours = (p.date.getTime() - anchor.date.getTime()) / 3_600_000;
    if (hours < MIN_SPAN_H) continue;
    const sent = p.n - anchor.n;
    const dryHours = periodS ? (sent * periodS) / 3600 : null;
    const heard = heardBetween(anchor.date.getTime(), p.date.getTime());
    windows.push({
      from: anchor.date,
      to: p.date,
      hours,
      sent,
      dryHours,
      dryFraction: dryHours !== null ? Math.min(1, dryHours / hours) : null,
      heard,
      heardPerSent: heard !== null && sent > 0 ? heard / sent : null,
      resting: !!restingSince && anchor.date >= restingSince,
    });
    anchor = p;
  }
  if (!windows.length) return null;

  const sum = (ws: CounterWindow[]) => {
    const hours = ws.reduce((a, w) => a + w.hours, 0);
    const sent = ws.reduce((a, w) => a + w.sent, 0);
    const heardKnown = ws.every((w) => w.heard !== null);
    const heard = heardKnown ? ws.reduce((a, w) => a + (w.heard ?? 0), 0) : null;
    const dryFraction = periodS ? Math.min(1, (sent * periodS) / 3600 / hours) : null;
    return {
      from: ws[0].from,
      to: ws[ws.length - 1].to,
      hours,
      sent,
      dryFraction,
      verdict: dryFraction !== null ? verdictOf(dryFraction) : null,
      heardPerSent: heard !== null && sent > 0 ? heard / sent : null,
    };
  };

  const restingWs = windows.filter((w) => w.resting);
  const afloatWs = restingSince ? windows.filter((w) => w.to <= restingSince) : [];
  const latest = sum(restingWs.length ? restingWs : windows);
  const afloat = afloatWs.length ? sum(afloatWs) : null;
  const afloatHeardPerSent = afloat?.heardPerSent ?? null;

  const rate = latest.sent / latest.hours;
  const span = `From ${fmt(latest.from)} to ${fmt(latest.to)}`;
  let reasoning =
    `${span} the tag's own counter rose by ${latest.sent.toLocaleString()} transmissions, ${rate.toFixed(0)} an hour` +
    (step ? ` (it reports in steps of ${step}, so short spans are merged)` : '') +
    '.';
  if (latest.dryFraction !== null && latest.verdict) {
    reasoning +=
      ` It transmits only when dry, once every ${periodS} s, so that is ${Math.round(latest.dryFraction * 100)}% of the time dry: ` +
      `${VERDICT_TEXT[latest.verdict]}.`;
  } else {
    reasoning += ' Without the tag’s transmission interval the count cannot be turned into hours dry.';
  }
  if (latest.heardPerSent !== null) {
    const pct = (x: number) => `${(x * 100).toFixed(x < 0.1 ? 1 : 0)}%`;
    reasoning += ` Satellites received ${pct(latest.heardPerSent)} of what it sent`;
    if (afloatHeardPerSent !== null && restingWs.length) {
      reasoning += `, against ${pct(afloatHeardPerSent)} while it floated`;
      const drop = latest.heardPerSent / afloatHeardPerSent;
      if (latest.verdict === 'dry' || latest.verdict === 'mostly_dry') {
        reasoning +=
          drop < 0.5
            ? '. It is dry and transmitting, so the missing messages are being blocked: something over or round it — a roof, a lid, a hull, a hand, vegetation — not water.'
            : '. It is dry, transmitting, and getting through about as well as afloat: open to the sky.';
      } else {
        reasoning += '.';
      }
    } else {
      reasoning += '.';
    }
  }
  if (latest.verdict === 'wet' || latest.verdict === 'partly_wet') {
    reasoning += ' A tag that is not transmitting cannot be heard however clear its sky: silence here is water, not a dead battery or a blocked antenna.';
  }

  return { step, periodS, windows, latest, afloatHeardPerSent, reasoning };
}
